    ('provincial-arbutus-grove-park', 'Arbutus Grove Park', 'provincial', 49.248767, -124.15096, 'Central Island', 'This park protects a representative stand of arbutus, Canada''s only native broadleaf evergreen. BC Parks describes the grove as a quiet nature-viewing spot used by local hikers; the site has no facilities or road access.', 'https://catalogue.data.gov.bc.ca/dataset/parks-ecological-reserves-and-protected-areas', 'BC Parks / DataBC — TANTALIS protected areas', '465', NULL),
