    ('provincial-helliwell-park', 'Helliwell Park', 'provincial', 49.500451, -124.600376, 'Northern Gulf Islands', 'A coastal trail follows the bluffs at St. John''s Point on Hornby Island, passing old-growth Douglas fir and Garry oak. The exposed headland looks across the Strait of Georgia to the Coast Mountains and offers chances to spot marine wildlife.', 'https://catalogue.data.gov.bc.ca/dataset/parks-ecological-reserves-and-protected-areas', 'BC Parks / DataBC — TANTALIS protected areas', '742', NULL),
    ('provincial-hemer-park', 'Hemer Park', 'provincial', 49.099372, -123.831412, 'Central Island', 'Easy trails wind through mature forest beside Holden Lake and its marshes south of Nanaimo. A viewing platform overlooks the wetland, making this a popular place for bird watching and quiet walks.', 'https://catalogue.data.gov.bc.ca/dataset/parks-ecological-reserves-and-protected-areas', 'BC Parks / DataBC — TANTALIS protected areas', '743', NULL),
    ('provincial-herald-park', 'Herald Park', 'provincial', 50.790602, -119.203354, 'Thompson & Okanagan', 'A BC provincial park in the Thompson & Okanagan collection. The map pin represents the largest official park polygon, not an entrance or trailhead.', 'https://catalogue.data.gov.bc.ca/dataset/parks-ecological-reserves-and-protected-areas', 'BC Parks / DataBC — TANTALIS protected areas', '744', NULL),
    ('provincial-hesquiat-lake-park', 'Hesquiat Lake Park', 'provincial', 49.501556, -126.387362, 'Central Island', 'This remote wilderness park on Clayoquot Sound''s Hesquiat Lake is reached by boat or float plane. Mature forest surrounds the lake, where visitors can fish and observe nature; there are no developed facilities and few visitors.', 'https://catalogue.data.gov.bc.ca/dataset/parks-ecological-reserves-and-protected-areas', 'BC Parks / DataBC — TANTALIS protected areas', '745', NULL),
