    ('provincial-sandwell-park', 'Sandwell Park', 'provincial', 49.186401, -123.816833, 'Gulf Islands', 'A short wooded walk on Gabriola Island ends at a picnic area above a sandy beach with views across the Strait of Georgia. At low tide, visitors can reach a sandstone petroglyph east of the day-use area.', 'https://catalogue.data.gov.bc.ca/dataset/parks-ecological-reserves-and-protected-areas', 'BC Parks / DataBC — TANTALIS protected areas', '1026', NULL),
    ('provincial-santa-gertrudis-boca-del-infierno-park', 'Santa Gertrudis-Boca Del Infierno Park', 'provincial', 49.610888, -126.627934, 'Central Island', 'This boat-access park in Nootka Sound supports kayaking, boating, wilderness camping, fishing and wildlife viewing. Sheltered anchorages at Boca del Infierno Bay and Santa Gertrudis Cove lie within a landscape shaped by Indigenous history and coastal travel.', 'https://catalogue.data.gov.bc.ca/dataset/parks-ecological-reserves-and-protected-areas', 'BC Parks / DataBC — TANTALIS protected areas', '1028', NULL),
