    ('regional-greenspaces-thompson-nicola-barriere-forks-regional-park-6066', 'Barriere Forks Regional Park', 'regional', 51.243073, -119.941855, 'Thompson & Okanagan', 'An officially mapped regional park in the Thompson & Okanagan collection. The pin represents its largest published polygon, not an entrance or trailhead.', 'https://catalogue.data.gov.bc.ca/dataset/6a2fea1b-0cc4-4fc2-8017-eaf755d516da', 'Thompson-Nicola Regional District via BC Local and Regional Greenspaces', '6066', NULL),
    ('regional-greenspaces-thompson-nicola-little-hell-s-gate-regional-park-6056', 'Little Hell''S Gate Regional Park', 'regional', 51.923719, -119.346031, 'Thompson & Okanagan', 'An officially mapped regional park in the Thompson & Okanagan collection. The pin represents its largest published polygon, not an entrance or trailhead.', 'https://catalogue.data.gov.bc.ca/dataset/6a2fea1b-0cc4-4fc2-8017-eaf755d516da', 'Thompson-Nicola Regional District via BC Local and Regional Greenspaces', '6056', NULL),
    ('regional-hamilton-marsh-regional-park-and-conservation-area', 'Hamilton Marsh Regional Park and Conservation Area', 'regional', 49.314008, -124.465592, 'Central Island', 'This 364-hectare property protects mature forest and a 36-hectare wetland within the French Creek watershed. Its marsh and surrounding forest are the defining features of this newly protected conservation area.', 'https://rdn.bc.ca/spatial-data-files', 'Regional District of Nanaimo — Regional Parks spatial data', NULL, NULL),
    ('regional-horne-lake-regional-park', 'Horne Lake Regional Park', 'regional', 49.343037, -124.742473, 'Central Island', 'Set below Mount Mark beside Horne Lake, this campground offers forest sites, canoe and stand-up paddleboard rentals, fishing and picnic space. It sits beside Horne Lake Caves Provincial Park and its cave tours.', 'https://rdn.bc.ca/spatial-data-files', 'Regional District of Nanaimo — Regional Parks spatial data', NULL, NULL),
    ('regional-horth-hill-regional-park', 'Horth Hill Regional Park', 'regional', 48.684372, -123.433748, 'Capital Region', 'Wooded slopes at the north end of the Saanich Peninsula lead to viewpoints over Satellite Channel, the peninsula and the Gulf Islands. The park covers about 36 hectares.', 'https://mapservices.crd.bc.ca/arcgis/rest/services/Basemap/Basemap/MapServer/3', 'Capital Regional District — Park GIS layer', NULL, NULL),
    ('regional-island-view-beach-regional-park', 'Island View Beach Regional Park', 'regional', 48.578208, -123.372294, 'Capital Region', 'A long sandy shoreline on the eastern Saanich Peninsula sits beside dunes, wetlands and coastal shrubs. Visitors come to walk, picnic and swim, while the beach and wetlands provide habitat for resident and migrating birds.', 'https://mapservices.crd.bc.ca/arcgis/rest/services/Basemap/Basemap/MapServer/3', 'Capital Regional District — Park GIS layer', NULL, NULL),
    ('regional-jordan-river-regional-park', 'Jordan River Regional Park', 'regional', 48.420658, -124.032081, 'Capital Region', 'A forest trail and stairway descend from the coastal park to Sandcut Beach, a long cobble shore on Juan de Fuca Strait. The route opens to views toward the Olympic Peninsula.', 'https://mapservices.crd.bc.ca/arcgis/rest/services/Basemap/Basemap/MapServer/3', 'Capital Regional District — Park GIS layer', NULL, NULL),
    ('regional-kapoor-regional-park', 'Kapoor Regional Park', 'regional', 48.490849, -123.714958, 'Capital Region', 'Following the Sooke River near the end of the Galloping Goose Regional Trail, Kapoor offers a quiet stretch of riverfront along old roads and trails. The park borders the historic Leechtown gold-rush site and former railway logging area.', 'https://mapservices.crd.bc.ca/arcgis/rest/services/Basemap/Basemap/MapServer/3', 'Capital Regional District — Park GIS layer', NULL, NULL),
    ('regional-kwaksistah-regional-park', 'Kwaksistah Regional Park', 'regional', 50.521979, -128.027444, 'North Island', 'This remote, free campground at Winter Harbour has eight first-come sites, picnic tables, fire pits and outhouses, with no water, power or sewer service. The approach follows an active logging road, so allow extra time and be prepared to yield to logging trucks.', 'https://www.rdmw.bc.ca/recreation-leisure/camping-information/kwaksistah-regional-park/', 'Regional District of Mount Waddington + OpenStreetMap contributors', 'W827164115', NULL),
    ('regional-little-huson-cave-regional-park', 'Little Huson Cave Regional Park', 'regional', 50.28532, -126.950779, 'North Island', 'A short forest path leads from the parking area to limestone arches, rock bridges and clear pools along Atluck Creek. The caves and karst formations are the main draw; water levels vary with rainfall and snowmelt.', 'https://www.rdmw.bc.ca/media/Huson%20Cave%20Park%20Overview%281%29.pdf', 'Regional District of Mount Waddington + OpenStreetMap contributors', 'W816998556', NULL),
    ('regional-little-qualicum-river-estuary-regional-conservation-area', 'Little Qualicum River Estuary Regional Conservation Area', 'regional', 49.366442, -124.496404, 'Central Island', 'This coastal sand spit at the mouth of the Little Qualicum River supports marine life and waterfowl. Access to the spit is restricted for conservation; the adjacent wildlife management area offers a place to observe the estuary.', 'https://rdn.bc.ca/spatial-data-files', 'Regional District of Nanaimo — Regional Parks spatial data', NULL, NULL),
    ('regional-little-qualicum-river-regional-park', 'Little Qualicum River Regional Park', 'regional', 49.32478, -124.548908, 'Central Island', 'This 111-hectare park follows both banks of the Little Qualicum River below Little Qualicum Falls. Rough trails lead to the river, while a developed route from Meadowood Way links with the provincial falls park.', 'https://rdn.bc.ca/spatial-data-files', 'Regional District of Nanaimo — Regional Parks spatial data', NULL, NULL),
    ('regional-lone-tree-hill-regional-park', 'Lone Tree Hill Regional Park', 'regional', 48.51953, -123.514555, 'Capital Region', 'A rocky climb reaches the 364-metre summit of Lone Tree Hill, with views of the Malahat, Highlands, Victoria and the Olympic Mountains. The park is named for a small, bonsai-like Douglas-fir once recognized as a heritage tree.', 'https://mapservices.crd.bc.ca/arcgis/rest/services/Basemap/Basemap/MapServer/3', 'Capital Regional District — Park GIS layer', NULL, NULL),
    ('regional-matheson-lake-regional-park', 'Matheson Lake Regional Park', 'regional', 48.362443, -123.60016, 'Capital Region', 'A loop trail circles the lake through a landscape of sensitive ecosystems, with a sandy beach for swimming and picnics in summer. The park connects with Roche Cove Regional Park and the Galloping Goose Regional Trail.', 'https://mapservices.crd.bc.ca/arcgis/rest/services/Basemap/Basemap/MapServer/3', 'Capital Regional District — Park GIS layer', NULL, NULL),
    ('regional-matthews-point-regional-park', 'Matthews Point Regional Park', 'regional', 48.863899, -123.32888, 'Capital Region', 'Woodland paths and coastal bluffs open onto views of Active Pass. The park protects shoreline ecosystems on Salt Spring Island and offers opportunities for hiking, birdwatching and horseback riding.', 'https://mapservices.crd.bc.ca/arcgis/rest/services/Basemap/Basemap/MapServer/3', 'Capital Regional District — Park GIS layer', NULL, NULL),
